const $ = id => document.getElementById(id);
let token, project, source = '', sectionPath = null, sectionMode = false, dirty = false, proposal = null, activeTab = 'editor', sections = [], templates = [], validationEpoch = 0;
let modDraft = [], modCatalog = new Map(), localModCatalog = new Map(), modDraftDirty = false, modUploadTarget = '';
async function api(path, body, method = 'POST') {
  const response = await fetch(path, body === undefined ? {} : {method, headers:{'Content-Type':'application/json','X-Workbench-Token':token},body:JSON.stringify(body)});
  const result = await response.json();
  if (!response.ok) throw new Error(typeof result.error === 'string' ? result.error : result.error?.message || `Request failed (${response.status})`);
  return result;
}
function status(message, error = false) { $('status').textContent = message; $('status').className = error ? 'error' : ''; if(error){const dialog=document.querySelector('dialog[open]');if(dialog){let box=dialog.querySelector('.dialog-error');if(!box){box=node('p',undefined,'dialog-error');dialog.append(box);}box.textContent=message;}} }
function run(fn) { return async (...args) => { try { await fn(...args); } catch(e) { status(e.message, true); } }; }
function node(tag, text, cls) { const el = document.createElement(tag); if(text !== undefined) el.textContent=text; if(cls) el.className=cls; return el; }
function markDirty(value=true) {dirty=value;if(value){validationEpoch++;$('validation').replaceChildren(node('div','Document changed. Run checks again for current results.','blank-state'));}  $('dirty').textContent=project ? value ? 'Unsaved changes' : 'Saved locally' : 'No project';$('dirty').className=`pill${value?' unsaved':''}`;}
function size() { $('size').textContent=`${new TextEncoder().encode($('editor').value).length.toLocaleString()} bytes`; }
async function fullText() { if (!sectionMode) source=$('editor').value; else source=(await api('/api/replace',{text:source,path:sectionPath,value:$('editor').value})).text; return source; }
async function inspect() { const result=await api('/api/inspect',{text:source});sections=result.sections||[];sections=sections.map(s=>({...s,path:[...(result.gameStatePath||[]),s.key]}));renderSections(); $('projectSubtitle').textContent=`${result.format || 'JSON document'} · ${sections.length} world sections · local project`; }
function renderSections() { $('sectionCount').textContent=sections.length; const filter=$('search').value.toLowerCase();$('sections').replaceChildren();for(const item of sections.filter(s=>s.key.toLowerCase().includes(filter))){const b=node('button');b.append(node('span',item.key),node('small',item.count ?? item.type));b.classList.toggle('selected',sectionPath?.join('\0')===item.path.join('\0'));b.onclick=run(async()=>{await fullText();sectionPath=item.path;await showEditor(true);await showTab('editor');renderSections();});$('sections').append(b);} }
async function showEditor(section=false) { sectionMode=section&&!!sectionPath;$('editor').value=sectionMode?(await api('/api/section',{text:source,path:sectionPath})).text:source;$('editorTitle').textContent=sectionMode?sectionPath.join(' / '):'World document';$('editorHint').textContent=sectionMode?'Edit this exact section · all other source retained':'Exact source · all fields retained';$('documentMode').classList.toggle('active',!sectionMode);$('sectionMode').classList.toggle('active',sectionMode);$('sectionMode').disabled=!sectionPath;$('sectionNotice').hidden=!sectionMode;size();if($('recordFields'))await loadRecordFields();if(dirty)cacheBuffer(); }
async function listProjects() {const r=await api('/api/projects');$('projects').replaceChildren();for(const p of r.projects||[]){const b=node('button',p.name||'Untitled world');b.classList.toggle('selected',p.id===project?.id);b.onclick=run(async()=>{if(project) await save();await openProject(p.id);});$('projects').append(b);} }
function clearProject(){validationEpoch++;project=null;source='';sectionPath=null;sectionMode=false;proposal=null;sections=[];dirty=false;modDraft=[];modDraftDirty=false;modCatalog.clear();localModCatalog.clear();$('editor').value='';$('sections').replaceChildren();$('sectionCount').textContent='';$('projectTitle').textContent='Build a world worth exploring.';$('projectSubtitle').textContent='A careful workspace for the worlds you imagine.';$('crumb').textContent='Select a project';$('empty').hidden=false;$('projectContent').hidden=true;$('archiveProject').hidden=true;$('importChanges').hidden=true;markDirty(false);if(worldAgent)worldAgent.projectChanged();if(mapEditor)mapEditor.projectChanged();if(publication)publication.projectChanged();if(characterExplorer)characterExplorer.projectChanged();if(imageUploads)void imageUploads.projectChanged();}
async function archiveProject(){if(!project)return;const name=project.name;if(!await askConfirm(`Move “${name}” to Trash? You can restore this local world later. This does not delete anything on Voyage.`))return;await save();if(dirty)throw new Error('A newer edit is still unsaved. Save it before moving this world to Trash.');const id=project.id;await api(`/api/projects/${encodeURIComponent(id)}/archive`,{version:project.version});localStorage.removeItem('voyage-draft-'+id);clearProject();await listProjects();status(`“${name}” moved to Trash.`);}
function confirmPermanentDelete(name){return new Promise(resolve=>{const dialog=node('dialog');const heading=node('h2','Permanently delete local world');const message=node('p',`This permanently removes “${name}” and its local checkpoints, revisions, agent history, and generated assets. This cannot be undone. It does not remove a world from Voyage.`);const label=node('label',`Type ${name} to confirm`);const input=node('input');input.autocomplete='off';input.setAttribute('aria-label',`Type ${name} to confirm`);const actions=node('div',undefined,'dialog-actions');const cancel=node('button','Cancel');const confirm=node('button','Delete permanently','danger');confirm.disabled=true;input.oninput=()=>{confirm.disabled=input.value!==name;};const finish=value=>{dialog.close();dialog.remove();resolve(value);};cancel.onclick=()=>finish(false);confirm.onclick=()=>finish(true);dialog.addEventListener('cancel',e=>{e.preventDefault();finish(false);});actions.append(cancel,confirm);dialog.append(heading,message,label,input,actions);document.body.append(dialog);dialog.showModal();input.focus();});}
async function renderTrash(){const {projects=[]}=await api('/api/projects/trash');const host=$('trashProjects');host.replaceChildren();if(!projects.length){host.append(node('p','Trash is empty.','blank-state'));return;}for(const p of projects){const row=node('div',undefined,'trash-row');const detail=node('div');detail.append(node('strong',p.name||'Untitled world'),node('small',`Moved to Trash ${new Date((p.archived_at||p.updated)*1000).toLocaleString()}`));const actions=node('div',undefined,'trash-actions');const restore=node('button','Restore');restore.onclick=run(async()=>{const restored=await api(`/api/projects/${encodeURIComponent(p.id)}/unarchive`,{version:p.version});$('trashDialog').close();await openProject(restored.id,restored);status(`“${p.name}” restored.`);});const remove=node('button','Delete permanently','danger');remove.onclick=run(async()=>{if(!await confirmPermanentDelete(p.name))return;await api(`/api/projects/${encodeURIComponent(p.id)}`,{version:p.version},'DELETE');localStorage.removeItem('voyage-draft-'+p.id);await renderTrash();status(`“${p.name}” permanently deleted from this workbench.`);});actions.append(restore,remove);row.append(detail,actions);host.append(row);}}
async function openProject(id, supplied) {validationEpoch++;project=supplied||await api(`/api/projects/${encodeURIComponent(id)}`);source=project.text;sectionPath=null;sectionMode=false;proposal=null;modDraft=[];modDraftDirty=false;modCatalog.clear();localModCatalog.clear();if(mapEditor)mapEditor.projectChanged();$('empty').hidden=true;$('projectContent').hidden=false;$('archiveProject').hidden=false;$('importChanges').hidden=false;$('projectTitle').textContent=project.name;$('crumb').textContent=project.name;markDirty(false);await showEditor();await inspect();await listProjects();await showTab('editor');renderHistory();renderProposal();await recoverBuffer();if(worldAgent)await worldAgent.projectChanged();if(publication)publication.projectChanged();if(characterExplorer)characterExplorer.projectChanged();if(imageUploads)void imageUploads.projectChanged();status(dirty?'Recovered an unsaved editing buffer. Review and save it.':'Project opened. Original source retained.');}
async function save() {
 if(!project)return;
 const pid=project.id;let editorBefore=$('editor').value;
 try{await fullText();}catch(e){if(!sectionMode)throw e;source=(await api('/api/replace-draft',{text:source,path:sectionPath,value:$('editor').value})).text;sectionPath=null;await showEditor(false);editorBefore=$('editor').value;}
 if(!dirty&&source===project.text)return;
 const saved=await api(`/api/projects/${encodeURIComponent(pid)}`,{text:source,version:project.version},'PUT');
 if(project.id!==pid)return;
 const nameChanged=project.name!==saved.name;project=saved;if(nameChanged){$('projectTitle').textContent=project.name;$('crumb').textContent=project.name;await listProjects();}const changedWhileSaving=$('editor').value!==editorBefore;
 markDirty(changedWhileSaving);
 if(changedWhileSaving)cacheBuffer();else localStorage.removeItem('voyage-draft-'+project.id);
 await inspect().catch(()=>{});status(changedWhileSaving?'Earlier edit saved. Newer typing is still unsaved.':'Working copy saved locally.');
}
function renderDiff(host,changes) {host.replaceChildren();if(!changes?.length){host.append(node('div','No changes to review.','blank-state'));return;}for(const c of changes){const card=node('article',undefined,'change');card.append(node('h3',`${c.kind.toUpperCase()}  /${(c.path||[]).map(x=>String(x).replaceAll('~','~0').replaceAll('/','~1')).join('/')}`));const grid=node('div',undefined,'change-grid');for(const [label,value] of [['Before',c.before],['After',c.after]]){const box=node('div');box.append(node('label',label),node('pre',value==null?'(absent)':typeof value==='string'?value:JSON.stringify(value)));grid.append(box);}card.append(grid);host.append(card);} }
async function showTab(name) {if(project&&activeTab==='editor'&&name!=='validation')await fullText();activeTab=name;for(const b of document.querySelectorAll('[data-tab]')){b.classList.toggle('active',b.dataset.tab===name);b.setAttribute('aria-selected',String(b.dataset.tab===name));}for(const p of document.querySelectorAll('[role=tabpanel]'))p.hidden=p.id!==`panel-${name}`;if(name==='map'&&mapEditor)await mapEditor.render();if(name==='characters'&&characterExplorer)await characterExplorer.render();if(name==='images'&&imageUploads)await imageUploads.refresh();if(name==='mods'&&!modDraftDirty)await loadMods();if(name==='changes'){const d=await api('/api/diff',{before:project.original,after:source});const changes=d.changes||[];renderDiff($('changes'),changes);$('changeCount').textContent=changes.length;}if(name==='history')renderHistory();if(name==='proposal')await loadProposalHistory();}
function renderHistory() {$('history').replaceChildren();for(const c of [...(project?.checkpoints||[])].reverse()){const row=node('div',undefined,'history-row');const info=node('div');info.append(node('strong',c.reason||'Checkpoint'),node('small',new Date(typeof c.created === "number" ? c.created * 1000 : c.created).toLocaleString()));const button=node('button','Restore');button.onclick=run(async()=>{if(!await askConfirm('Restore this checkpoint? Your current draft will be saved first.'))return;await save();const p=await api(`/api/projects/${project.id}/restore`,{checkpointId:c.id,version:project.version});await openProject(p.id,p);status('Checkpoint restored.');});row.append(info,button);$('history').append(row);}if(!$('history').children.length)$('history').append(node('div','Create a checkpoint to preserve a named version of your world.','blank-state'));}
function renderProposal(){ $('proposalActions').hidden=!proposal;if(!proposal){$('proposalChanges').className='blank-state';$('proposalChanges').textContent='No proposal loaded. Your working copy stays untouched until acceptance.';}else{$('proposalChanges').className='';renderDiff($('proposalChanges'),proposal.changes);} }
function renderChecks(host,result,official=false){host.replaceChildren();const data=result.data||result;const errors=data.errors||[],warnings=data.warnings||[];host.append(node('strong',official?'Official Voyage draft validation':'Local document checks','validation-source'));if(!errors.length)host.append(node('div',official?(data.valid===true?'Official Voyage draft validation passed.':'Official validation returned no listed errors; inspect status.'): 'No local errors detected. Review advisory warnings below; these checks do not certify Voyage acceptance or gameplay.','check'));if(official&&errors.some(item=>String(typeof item==='string'?item:item?.message||'').includes('successLevelSettings')&&String(typeof item==='string'?item:item?.message||'').includes('undefined')))host.append(node('div','Voyage reports that successLevelSettings is missing. It expects firstSuccessfulTierId and a tiers array. Restore these values from a known-good world or add them deliberately, then validate again.','check warning'));for(const [items,cls,label] of [[errors,'error','Error'],[warnings,'warning','Warning']])for(const item of items)host.append(node('div',`${label}: ${typeof item==='string'?item:[item.path?JSON.stringify(item.path):'',item.message||JSON.stringify(item)].join(' ')}`,`check ${cls}`));host.append(node('p',`Checked ${new Date().toLocaleTimeString()}. Results apply to this document version only.`,'small'));}
$('editor').addEventListener('input',()=>{markDirty();size();cacheBuffer();$('validation').replaceChildren(node('div','Document changed. Run checks again for current results.','blank-state'));});
$('editor').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const a=e.target.selectionStart,b=e.target.selectionEnd;e.target.setRangeText('  ',a,b,'end');markDirty();size();}});
$('search').oninput=renderSections;
for(const button of document.querySelectorAll('[data-tab]'))button.onclick=run(()=>showTab(button.dataset.tab));
$('documentMode').onclick=run(async()=>{await fullText();await showEditor(false);});$('sectionMode').onclick=run(async()=>{await fullText();await showEditor(true);});
$('save').onclick=run(save);$('refreshDiff').onclick=run(()=>showTab('changes'));
$('archiveProject').onclick=run(archiveProject);
$('openTrash').onclick=run(async()=>{await renderTrash();$('trashDialog').showModal();});
$('importChanges').onclick=()=>{if(project)$('changesInput').click();};
$('changesInput').onchange=run(async()=>{const file=$('changesInput').files[0];$('changesInput').value='';if(!file||!project)return;await save();if(dirty)throw new Error('A newer edit is still unsaved. Save it before importing external changes.');const id=project.id,name=project.name,version=project.version;const text=await file.text();try{JSON.parse(text);}catch(e){throw new Error(`“${file.name}” is not valid JSON: ${e.message}`);}if(!await askConfirm(`Apply “${file.name}” to “${name}” as one local Git revision? The current world will be checkpointed first.`))return;const result=await api(`/api/projects/${encodeURIComponent(id)}/import-changes`,{text,version,reason:`Import external JSON: ${file.name}`});localStorage.removeItem('voyage-draft-'+id);await openProject(id,result.project);status(`Imported “${file.name}” as one revision (${result.changes?.length??0} JSON changes).`);});
$('checkpoint').onclick=run(async()=>{if(!project)return;const reason=await askText('Checkpoint name','Before the next adventure');if(!reason)return;await save();const p=await api(`/api/projects/${project.id}/checkpoints`,{reason,version:project.version});project=p.project||p;if(!project.text)project=await api(`/api/projects/${project.id}`);renderHistory();status('Checkpoint created.');});
$('runValidation').onclick=run(async()=>{if(!project)return;const epoch=validationEpoch,pid=project.id;try{let candidate;try{candidate=await fullText();}catch(error){if(!sectionMode)throw error;candidate=(await api('/api/replace-draft',{text:source,path:sectionPath,value:$('editor').value})).text;}if(epoch!==validationEpoch||project?.id!==pid){status('Document changed while checks ran. Run local checks again.');return;}const result=await api('/api/validate',{text:candidate});if(epoch!==validationEpoch||project?.id!==pid){status('Document changed while checks ran. Run local checks again.');return;}renderChecks($('validation'),result);status(result.errors?.length?`Local checks found ${result.errors.length} error(s).`:'Local checks finished.');}catch(error){if(project?.id===pid)$('validation').replaceChildren(node('div',`Local checks could not run: ${error.message}`,'check error'));throw error;}});
$('newProject').onclick=()=>$('createDialog').showModal();$('confirmNew').onclick=run(async e=>{e.preventDefault();const name=$('newName').value.trim();if(!name)return;if(project)await save();const p=await api(`/api/templates/${$('newTemplate').value}`,{name});$('createDialog').close();await openProject(p.id,p);});
$('importWorld').onclick=$('emptyImport').onclick=()=>$('fileInput').click();
$('fileInput').onchange=run(async()=>{const file=$('fileInput').files[0];$('fileInput').value='';if(!file)return;if(project)await save();const p=await api('/api/projects',{name:file.name.replace(/\.json$/i,''),text:await file.text()});await openProject(p.id,p);});
$('exportWorld').onclick=run(async()=>{if(!project)return;await fullText();if(modDraftDirty)throw new Error('Apply the pending mod reference changes before exporting.');const {mods}=await api('/api/mods/inspect',{text:source});$('exportWithMods').textContent=`With mod overlays (${mods.length})`;$('exportDialog').showModal();});
$('cancelExport').onclick=()=>$('exportDialog').close();
async function downloadWorld(mode){if(!project)return;const {text}=await api('/api/mods/export',{text:source,mods:mode==='base'?[]:undefined});const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=node('a');a.href=url;a.download=`${project.name.replace(/[^\w -]/g,'_')||'world'}-${mode}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('exportDialog').close();status(mode==='base'?'Exported base JSON without mod references. Already merged content remains in world sections.':'Exported current JSON with its ordered mod references.');}
$('exportBase').onclick=run(()=>downloadWorld('base'));
$('exportWithMods').onclick=run(()=>downloadWorld('mods'));
async function loadMods(){if(!project)return;const result=await api('/api/mods/inspect',{text:source});modDraft=result.mods.map(m=>({...m}));modDraftDirty=false;await loadLocalModFiles();const connection=await api('/api/connection');if(connection.connected&&modDraft.length){try{await resolveMods();}catch(error){$('modConnection').textContent=`Voyage mod lookup failed: ${error.message}. Attached JSON can still identify IDs.`;}}else $('modConnection').textContent=connection.connected?'Add a mod ID or attach mod JSON to identify it.':'Connect your Creator API key or attach mod JSON files to resolve names. Unknown IDs remain visible.';}
function renderMods(){const host=$('modList');host.replaceChildren();if(!modDraft.length)host.append(node('p','No mod overlays referenced by this world.','blank-state'));for(const [index,mod] of modDraft.entries()){const meta=localModCatalog.get(mod.shortId)||modCatalog.get(mod.shortId);const row=node('div',undefined,'mod-row');const detail=node('div');detail.append(node('strong',`${index+1}. ${meta?.title||'Unresolved mod'}`),node('small',`${mod.shortId} · ${mod.version==null?'latest published version':`version ${mod.version}`} · ${meta?.source||'ID not resolved'}`));if(meta?.description)detail.append(node('p',meta.description));if(meta?.sections?.length)detail.append(node('p',`Attached sections: ${meta.sections.map(s=>`${s.name} (${s.entries})`).join(', ')}`));const actions=node('div',undefined,'mod-row-actions');for(const [label,target] of [['↑',index-1],['↓',index+1]]){const button=node('button',label);button.setAttribute('aria-label',`${label==='↑'?'Move up':'Move down'} ${mod.shortId}`);button.disabled=target<0||target>=modDraft.length;button.onclick=()=>{[modDraft[index],modDraft[target]]=[modDraft[target],modDraft[index]];modDraftDirty=true;renderMods();};actions.append(button);}const version=node('input');version.type='number';version.min='1';version.step='1';version.placeholder='Latest';version.value=mod.version??'';version.setAttribute('aria-label',`Version for ${mod.shortId}; blank means latest`);version.onchange=run(async()=>{const raw=version.value.trim();const parsed=raw?Number(raw):null;if(raw&&(!Number.isSafeInteger(parsed)||parsed<1))throw new Error('Mod version must be a positive whole number or blank for latest.');mod.version=parsed;modDraftDirty=true;renderMods();});const attach=node('button',meta?.source==='attached JSON'?'Replace JSON':'Attach JSON');attach.onclick=()=>{modUploadTarget=mod.shortId;$('modFileInput').click();};const remove=node('button','Remove');remove.onclick=()=>{modDraft.splice(index,1);modDraftDirty=true;renderMods();};actions.append(version,attach,remove);row.append(detail,actions);host.append(row);} $('applyMods').disabled=!modDraftDirty;}
async function loadLocalModFiles(){if(!project)return;const result=await api(`/api/projects/${encodeURIComponent(project.id)}/mod-files`,undefined,'GET');localModCatalog=new Map((result.mods||[]).map(m=>[m.shortId,m]));renderMods();renderLocalModFiles();}
function renderLocalModFiles(){const host=$('localModList');host.replaceChildren();if(!localModCatalog.size){host.append(node('p','No mod JSON files attached.','blank-state'));return;}for(const mod of localModCatalog.values()){const row=node('div',undefined,'mod-row');const detail=node('div');detail.append(node('strong',mod.title),node('small',`${mod.shortId} · ${mod.filename} · ${modDraft.some(m=>m.shortId===mod.shortId)?'active reference':'not in current stack'}`));if(mod.sections?.length)detail.append(node('p',`Nonempty sections: ${mod.sections.map(s=>`${s.name} (${s.entries})`).join(', ')}`));const actions=node('div',undefined,'mod-row-actions');const download=node('button','Download JSON');download.onclick=run(async()=>{const result=await api(`/api/projects/${encodeURIComponent(project.id)}/mod-files/download`,{shortId:mod.shortId});const url=URL.createObjectURL(new Blob([result.text],{type:'application/json'}));const link=node('a');link.href=url;link.download=result.filename.replace(/[^\w. -]/g,'_')||'mod.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});const detach=node('button','Detach');detach.onclick=run(async()=>{await api(`/api/projects/${encodeURIComponent(project.id)}/mod-files/detach`,{shortId:mod.shortId});await loadLocalModFiles();status(`Detached local JSON for ${mod.shortId}; the world reference is unchanged.`);});actions.append(download,detach);row.append(detail,actions);host.append(row);}}
$('addMod').onclick=run(async()=>{const shortId=$('modId').value.trim(),raw=$('modVersion').value.trim(),version=raw?Number(raw):null;if(!shortId)throw new Error('Enter a mod short ID.');if(modDraft.some(m=>m.shortId===shortId))throw new Error('This mod is already in the stack.');if(raw&&(!Number.isSafeInteger(version)||version<1))throw new Error('Mod version must be a positive whole number or blank for latest.');modDraft.push({shortId,version});modDraftDirty=true;$('modId').value='';$('modVersion').value='';renderMods();});
$('attachMod').onclick=()=>{if(!project)return;modUploadTarget=$('modId').value.trim();$('modFileInput').click();};
$('modFileInput').onchange=run(async()=>{const file=$('modFileInput').files[0];$('modFileInput').value='';if(!file||!project)return;if(file.size>8*1024*1024)throw new Error('Mod JSON must be no larger than 8 MiB.');const pid=project.id;const info=await api(`/api/projects/${encodeURIComponent(pid)}/mod-files`,{shortId:modUploadTarget,filename:file.name,text:await file.text()});modUploadTarget='';if(project?.id!==pid)return;if(!modDraft.some(m=>m.shortId===info.shortId)){modDraft.push({shortId:info.shortId,version:null});modDraftDirty=true;}await loadLocalModFiles();$('modId').value='';status(`Attached ${info.filename} to ${info.shortId}. ${modDraftDirty?'Apply the reference changes to include it in the world.':'The world reference is unchanged.'}`);});
$('applyMods').onclick=run(async()=>{if(!project)return;const result=await api('/api/mods/export',{text:source,mods:modDraft});if(result.text===source){modDraftDirty=false;renderMods();return;}source=result.text;sectionPath=null;markDirty();await showEditor(false);await inspect();modDraftDirty=false;renderMods();status('Mod references updated in the working copy. Save locally to record this revision.');});
async function resolveMods(){const ids=modDraft.map(m=>m.shortId);const result=await api('/api/remote/mods',{shortIds:ids});modCatalog=new Map((result.mods||[]).map(m=>[m.shortId,m]));renderMods();$('modConnection').textContent=`Resolved ${ids.filter(id=>modCatalog.has(id)).length} of ${ids.length} active IDs from your Voyage mod catalog. Unlisted IDs remain unresolved.`;}
$('refreshMods').onclick=run(async()=>{if(!project)return;await resolveMods();});
$('importProposal').onclick=()=>$('proposalInput').click();$('proposalInput').onchange=run(async()=>{const f=$('proposalInput').files[0];$('proposalInput').value='';if(!f)return;await fullText();const text=await f.text(),d=await api('/api/diff',{before:source,after:text});proposal={text,base:source,version:project.version,changes:d.changes};renderProposal();status('Proposal ready for review.');});
$('rejectProposal').onclick=()=>{proposal=null;renderProposal();status('Proposal discarded.');};$('acceptProposal').onclick=run(async()=>{await fullText();const latest=await api(`/api/projects/${project.id}`);if(source!==proposal.base||latest.version!==proposal.version)throw new Error('The working copy changed since proposal import. Import it again against the current copy.');const candidate=proposal.text,acceptedBase=proposal.base;await save();await fullText();if(source!==acceptedBase)throw new Error('Document changed during acceptance. Review the proposal again.');project=await api(`/api/projects/${project.id}/checkpoints`,{reason:'Before accepting proposal',version:project.version});source=candidate;proposal=null;markDirty();await showEditor(false);renderProposal();await inspect();await showTab('editor');status('Proposal accepted locally. Review or save when ready.');});
