async function refreshTemplates(){const result=await api('/api/templates');templates=Array.isArray(result)?result:result.templates||[];$('templates').replaceChildren();const select=$('newTemplate'),selected=select.value;select.replaceChildren();for(const t of templates){const option=node('option',t.name||t.title||t.id);option.value=t.id;select.append(option);const b=node('button',undefined,'template-card');b.append(node('strong',t.name||t.title||t.id),node('small',t.description||'Open a local working copy'));b.onclick=run(async()=>{if(project)await save();const p=await api(`/api/templates/${encodeURIComponent(t.id)}`,{});await openProject(p.id,p);});$('templates').append(b);}if(templates.some(t=>t.id===selected))select.value=selected;}
async function init(){const s=await api('/api/session');token=s.token;await listProjects();await refreshTemplates();initBaseWorld({api,node,status,refreshTemplates});setupTrash();setupBuilder();setupAgent();mapEditor=initMapEditor({api,node,getSource:()=>source,getProject:()=>project,applyText:async text=>{source=text;sectionPath=null;markDirty();await showEditor(false);await inspect();},status,confirm:message=>askConfirm(message)});imageUploads=initImageUploads({api,node,getProject:()=>project,status});characterExplorer=initCharacterExplorer({api,node,getSource:()=>source,getProject:()=>project,applyText:async text=>{source=text;sectionPath=null;markDirty();await showEditor(false);await inspect();},status,showTab,uploadPortrait:callback=>imageUploads.open({target:'NPC_PORTRAIT',onUploaded:callback})});const imageTab=node('button','Image uploads');imageTab.dataset.tab='images';imageTab.setAttribute('role','tab');imageTab.setAttribute('aria-selected','false');document.querySelector('.tabs').append(imageTab);const imagePanel=node('section',undefined,'panel padded');imagePanel.id='panel-images';imagePanel.setAttribute('role','tabpanel');imagePanel.hidden=true;imagePanel.append(imageUploads.createPanel());$('projectContent').append(imagePanel);imageTab.onclick=run(()=>showTab('images'));worldAgent=initWorldAgent({api,node,getProject:()=>project,save,openProject,status,showTab,uploadImage:assetId=>imageUploads.open({assetId})});await setupConnection();publication=initPublication({api,node,getProject:()=>project,getDirty:()=>dirty,save,openProject,showTab,status,confirm:message=>askConfirm(message)});status('Local companion connected. Import a world or choose a starting point.');}
