function setupTrash(){const dialog=node('dialog');dialog.id='trashDialog';const heading=node('h2','Trash');const explanation=node('p','Local worlds moved to Trash can be restored. Permanent deletion also removes their local revisions, agent history, and generated assets.');const projects=node('div');projects.id='trashProjects';const actions=node('div',undefined,'dialog-actions');const close=node('button','Close');close.onclick=()=>dialog.close();actions.append(close);dialog.append(heading,explanation,projects,actions);document.body.append(dialog);}
function setupBuilder() {
 const toolbar=node('div',undefined,'record-toolbar');
 toolbar.innerHTML='<div id="pathCrumbs" class="path-crumbs"></div><div class="record-actions"><button id="upRecord">↑ Parent</button><button id="addRecord">+ Add field / record</button><button id="removeRecord">Remove selected</button></div><div id="recordFields"></div><details id="referenceDetails"><summary>Section reference</summary><div id="referenceHelp"></div></details>';
 $('panel-editor').insertBefore(toolbar,$('editor'));
 const dialog=node('dialog');dialog.id='fieldDialog';dialog.innerHTML='<h2 id="fieldHeading">Edit value</h2><p id="fieldHint"></p><label for="fieldKey">Key</label><input id="fieldKey"><label for="fieldValue">Value</label><textarea id="fieldValue" spellcheck="false"></textarea><div class="dialog-actions"><button id="cancelField">Cancel</button><button id="applyField" class="primary">Apply change</button></div><p id="fieldError" role="alert"></p>';
 document.body.append(dialog);$('cancelField').onclick=()=>dialog.close();
 $('upRecord').onclick=run(async()=>{await fullText();sectionPath=sectionPath?.slice(0,-1)||[];await showEditor(sectionPath.length>0);});
 $('addRecord').onclick=run(async()=>{await fullText();const path=sectionMode?sectionPath:[];const info=await api('/api/describe',{text:source,path});if(!['object','array'].includes(info.type))throw new Error('Open an object or array to add a value.');await fieldDialog(path,null,info.type);});
 $('removeRecord').onclick=run(async()=>{await fullText();if(!sectionMode||!sectionPath.length)throw new Error('Select a field or record first.');if(!await askConfirm(`Remove “${sectionPath.at(-1)}”? A safety checkpoint will be created.`))return;await save();project=await api(`/api/projects/${project.id}/checkpoints`,{reason:'Before removing '+sectionPath.at(-1),version:project.version});source=(await api('/api/mutate',{text:source,path:sectionPath.slice(0,-1),action:'remove',key:sectionPath.at(-1)})).text;sectionPath=sectionPath.slice(0,-1);markDirty();await showEditor(sectionPath.length>0);await inspect();});
}
async function fieldDialog(path,field,containerType) {
 const adding=field===null;const target=adding?path:[...path,field.key];
 const raw=adding?'{}':(await api('/api/section',{text:source,path:target})).text;
 const isString=field?.type==='string';
 $('fieldHeading').textContent=adding?'Add a field or record':`Edit ${field.key}`;
 $('fieldHint').textContent=isString?'Edit the full text. Quoting and escaping are handled for you.':'Enter a JSON value: an object, array, quoted string, number, true, false, or null. Numbers retain their exact spelling.';
 $('fieldKey').value=adding?'':String(field.key);$('fieldKey').disabled=!adding||containerType==='array';
 $('fieldValue').value=isString?JSON.parse(raw):raw;$('fieldError').textContent='';$('fieldDialog').showModal();
 $('applyField').onclick=async()=>{try{const value=isString?JSON.stringify($('fieldValue').value):$('fieldValue').value;
 if(adding){if(containerType!=='array'&&!$('fieldKey').value)throw new Error('Enter a key.');source=(await api('/api/mutate',{text:source,path,action:containerType==='array'?'append':'add',key:$('fieldKey').value,value})).text;}
 else source=(await api('/api/replace',{text:source,path:target,value})).text;
 markDirty();$('fieldDialog').close();await showEditor(sectionMode);await inspect();status('Value updated. Save locally when ready.');
 }catch(e){$('fieldError').textContent=e.message;}};
}
let referenceCache;
async function loadRecordFields(){
 const host=$('recordFields');host.replaceChildren();$('pathCrumbs').replaceChildren();
 const path=sectionMode?sectionPath:[];
 const crumbs=[{label:'World',path:[]},...path.map((key,i)=>({label:String(key),path:path.slice(0,i+1)}))];
 for(const crumb of crumbs){const b=node('button',crumb.label);b.onclick=run(async()=>{await fullText();sectionPath=crumb.path;await showEditor(crumb.path.length>0);});$('pathCrumbs').append(b);}
 $('upRecord').disabled=!path.length;$('removeRecord').disabled=!path.length;
 let result;try{result=await api('/api/describe',{text:source,path});}catch{host.append(node('p','Fix JSON syntax to use structured editing. Your source can still be saved.'));return;}
 $('addRecord').disabled=!['object','array'].includes(result.type);
 const list=node('div',undefined,'field-list');
 for(const field of result.children||[]){const row=node('div',undefined,'field-row');const name=node('button',String(field.key));name.title=field.preview;name.onclick=run(async()=>{await fullText();sectionPath=[...path,field.key];await showEditor(true);});row.append(name,node('span',field.type));
 const edit=node('button','Edit');edit.setAttribute('aria-label',`Edit ${field.key}`);edit.onclick=run(async()=>{await fullText();await fieldDialog(path,field);});row.append(edit);list.append(row);}
 host.append(list);$('referenceHelp').replaceChildren();
 try{referenceCache ||= await api('/api/reference');const key=path.find(p=>sections.some(s=>s.key===p));const matches=referenceCache.filter(r=>r.section===key);for(const ref of matches.slice(0,2)){$('referenceHelp').append(node('strong',ref.title),node('p',ref.summary||'Cached community reference.'));}}catch{}
}
async function setupConnection(){
 const b=node('button','⚙ Voyage connection','outline wide');$('importWorld').after(b);
 const dialog=node('dialog');dialog.id='connectionDialog';
 dialog.innerHTML='<h2>Connect to Voyage</h2><p>Creator API keys are saved by the companion on this machine, outside project JSON and exports. Linux uses an owner-only file; Windows encrypts the file for this account.</p><label for="environment">Environment</label><select id="environment"><option value="production" disabled>Production — not ready</option><option value="alpha" selected>Alpha</option></select><label for="apiKey">Creator API key</label><input id="apiKey" type="password" autocomplete="off" placeholder="Paste a key, or leave blank to use a saved key"><div class="dialog-actions"><button id="closeConnection">Close</button><button id="connectVoyage" class="primary">Connect / use saved key</button><button id="forgetVoyage">Forget saved key</button></div><div id="connectionStatus" role="status"></div><hr><h3>Open an owned world</h3><button id="listRemote">List owned worlds</button><div id="remoteList"></div><label for="remoteId">World short ID</label><input id="remoteId" placeholder="World short ID"><button id="downloadRemote" class="primary">Download to new local project</button>';
 document.body.append(dialog);
 const ownedWorlds=initRemoteWorldList({api,listButton:$('listRemote'),listContainer:$('remoteList'),onSelect:w=>{$('remoteId').value=w.shortId||w.id||'';}});
 async function connectionStatus(){const result=await api('/api/connection',undefined,'GET');$('environment').value=result.environment;$('connectionStatus').textContent=result.credentialError||`${result.connected?'Connected':'Not connected'} to ${result.environment}. Saved keys: ${(result.savedEnvironments||[]).join(', ')||'none'}.`;return result;}
 b.onclick=run(async()=>{await connectionStatus();dialog.showModal();});
 $('closeConnection').onclick=()=>dialog.close();
 $('connectVoyage').onclick=run(async()=>{const result=await api('/api/connection',{key:$('apiKey').value.trim(),environment:$('environment').value});$('apiKey').value='';ownedWorlds.reset();$('connectionStatus').textContent=`Connected to ${result.environment}. Saved keys: ${(result.savedEnvironments||[]).join(', ')}.`;});
 $('forgetVoyage').onclick=run(async()=>{const env=$('environment').value;if(!await askConfirm(`Forget the saved ${env} Creator API key from this machine?`))return;await api('/api/connection',{environment:env},'DELETE');$('apiKey').value='';ownedWorlds.reset();await connectionStatus();});
 $('downloadRemote').onclick=run(async()=>{const shortId=$('remoteId').value.trim();if(!shortId)throw new Error('Enter a world short ID.');if(project)await save();if(dirty)throw new Error('Save your latest local edits before opening another world.');const p=await api('/api/remote/download',{shortId});await openProject(p.id,p);dialog.close();status('Owned world downloaded. Exact source and remote revision retained.');});
 const validate=node('button','Validate with Voyage');
 validate.onclick=run(async()=>{if(!project)return;const pid=project.id,epoch=validationEpoch;try{await fullText();await showTab('validation');if(epoch!==validationEpoch||project?.id!==pid){status('Document changed while validation ran. Run it again.');return;}const result=await api('/api/remote/validate',{text:source});if(epoch!==validationEpoch||project?.id!==pid){status('Document changed while validation ran. Run it again.');return;}renderChecks($('validation'),result,true);const data=result.data||result;status(data.valid===true?'Official Voyage draft validation passed.':(data.errors||[]).length?`Official Voyage validation found ${data.errors.length} issue(s).`:'Official Voyage validation did not pass; no detailed issues were returned.');}catch(error){if(project?.id===pid)$('validation').replaceChildren(node('div',`Official Voyage validation could not run: ${error.message}`,'check error'));throw error;}});
 $('runValidation').before(validate);
 const remoteSave=node('button','Save to Voyage');
 remoteSave.onclick=run(async()=>{if(!project)return;await save();if(dirty)throw new Error('Newer edits are still unsaved. Save them locally before sending to Voyage.');if(!await askConfirm('Validate and save this linked draft to Voyage? This updates the remote draft using its downloaded revision.'))return;const result=await api(`/api/projects/${project.id}/remote-save`,{version:project.version});await openProject(result.project.id,result.project);if(result.changes?.length){proposal={text:result.remoteText,base:source,version:project.version,changes:result.changes};renderProposal();await showTab('proposal');}status(result.localChangedDuringSave?'Remote saved an earlier local version; newer local edits remain unsynchronized.':result.changes?.length?'Remote save verified. Review Voyage’s normalization changes as a proposal.':'Remote draft saved and verified by read-back.');});
 $('save').after(remoteSave);
 const refresh=node('button','Refresh linked world');
 remoteSave.after(refresh);
 refresh.onclick=run(async()=>{if(!project)return;await save();if(dirty)throw new Error('Newer edits are still unsaved. Save them locally before refreshing.');const pid=project.id;const result=await api(`/api/projects/${encodeURIComponent(pid)}/remote-refresh`,{version:project.version});if(project?.id!==pid)return;if(result.status==='unchanged'||result.status==='matches-local'){project=result.project;status(result.status==='matches-local'?'Downloaded Voyage draft matches this working copy. The save outcome is reconciled.':'Voyage draft is unchanged. The linked revision and save outcome are reconciled.');return;}showRemoteRefreshPreview(result,pid,project.version);});
}
function showRemoteRefreshPreview(preview,pid,version){
 const dialog=node('dialog');dialog.className='remote-refresh-dialog';
 const heading=node('h2','Review linked Voyage draft');
 const summary=node('p',preview.hasLocalChanges?'The live Voyage draft differs from this project and this project has local edits. Applying the download will replace the local working copy; its current text is preserved in a checkpoint and Git revision.':'The live Voyage draft differs from this project. Applying the download will update this same project and preserve the current text in a checkpoint and Git revision.');
 const detail=node('p',`${preview.changes.length} JSON change${preview.changes.length===1?'':'s'} found. Review the sample below before applying.`);
 const changes=node('div',undefined,'remote-refresh-changes');renderDiff(changes,preview.changes.slice(0,20));
 const controls=node('div',undefined,'dialog-actions');const cancel=node('button','Keep local copy');const apply=node('button','Apply downloaded draft','primary');
 const close=()=>{dialog.close();dialog.remove();};cancel.onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 apply.onclick=run(async()=>{apply.disabled=true;try{if(project?.id!==pid||project.version!==version)throw new Error('Project changed. Refresh the linked world again.');const result=await api(`/api/projects/${encodeURIComponent(pid)}/remote-refresh`,{version,apply:true,expectedEtag:preview.etag});close();await openProject(pid,result.project);status('Linked Voyage draft applied to this project. The prior local text is in History and Git revisions.');}finally{apply.disabled=false;}});
 controls.append(cancel,apply);dialog.append(heading,summary,detail,changes,controls);document.body.append(dialog);dialog.showModal();
}
let activeAgentJob=null;
function setupAgent(){
 const box=node('div',undefined,'agent-box');
 box.innerHTML='<label for="agentInstruction">Ask Codex for a focused edit</label><textarea id="agentInstruction" placeholder="Deepen this character’s description while preserving its mechanics…"></textarea><div class="agent-controls"><span id="agentScope">Selected section or record is sent to Codex. Proposals stay local until you accept them.</span><div><button id="cancelAgent" hidden>Cancel run</button> <button id="generateProposal" class="primary">Generate proposal</button></div></div><div id="agentProgress" role="status"></div><details><summary>Proposal history</summary><div id="agentHistory"></div></details>';
 $('panel-proposal').insertBefore(box,$('proposalChanges'));
 $('panel-proposal').querySelector('.notice').textContent='Codex edits are staged for review. Proposal history survives browser and companion restarts.';
 $('cancelAgent').onclick=run(async()=>{if(activeAgentJob)await api(`/api/agent/proposals/${activeAgentJob}/cancel`,{});});
 $('generateProposal').onclick=run(async()=>{
  await fullText();if(!sectionPath)throw new Error('Select a section or record in the editor first.');
  const instruction=$('agentInstruction').value.trim();if(!instruction)throw new Error('Describe the requested change.');
  const job=await api('/api/agent/proposals',{text:source,path:sectionPath,instruction,projectId:project.id,version:project.version});
  await watchProposal(job.id,project.id);
 });
}
async function watchProposal(id,projectId){
 activeAgentJob=id;$('generateProposal').disabled=true;$('cancelAgent').hidden=false;
 $('agentProgress').textContent='Codex is preparing a staged proposal. You can keep editing; acceptance checks for conflicts.';
 try{
  let result=await api(`/api/agent/proposals/${id}`);
  while(result.status==='running'){await new Promise(resolve=>setTimeout(resolve,1500));result=await api(`/api/agent/proposals/${id}`);}
  if(result.status!=='complete')throw new Error(result.error||`Proposal ${result.status}.`);
  if(project?.id===projectId){proposal={text:result.text,base:result.baseText,version:result.version,changes:result.changes};renderProposal();$('agentProgress').textContent=result.explanation;status('Codex proposal ready for review.');}
  else status('Proposal completed and is saved in its project’s proposal history.');
 }catch(e){$('agentProgress').textContent=e.message;status(e.message,true);}
 finally{activeAgentJob=null;$('generateProposal').disabled=false;$('cancelAgent').hidden=true;await loadProposalHistory();}
}
async function loadProposalHistory(){
 if(!project||!$('agentHistory'))return;
 const {jobs}=await api(`/api/projects/${project.id}/proposals`);const host=$('agentHistory');host.replaceChildren();
 if(!jobs.length){host.append(node('p','No Codex runs for this project yet.'));return;}
 for(const job of jobs){const row=node('div',undefined,'history-row');const info=node('div');info.append(node('strong',job.instruction),node('small',`${job.status} · ${new Date(job.created*1000).toLocaleString()}`));if(job.error)info.append(node('small',job.error));row.append(info);
 if(['complete','running'].includes(job.status)){const button=node('button',job.status==='running'?'Watch run':'Review');button.onclick=run(()=>watchProposal(job.id,project.id));row.append(button);}
 if(job.status==='running'){const cancel=node('button','Cancel');cancel.onclick=run(async()=>{await api(`/api/agent/proposals/${job.id}/cancel`,{});await loadProposalHistory();});row.append(cancel);}
 host.append(row);}
}

function cacheBuffer(){if(!project)return;try{localStorage.setItem('voyage-draft-'+project.id,JSON.stringify({version:project.version,source,path:sectionMode?sectionPath:null,buffer:$('editor').value}));}catch{status('Browser recovery storage is full. Save locally to preserve this edit.',true);}}
async function recoverBuffer(){const raw=localStorage.getItem('voyage-draft-'+project.id);if(!raw)return;try{const draft=JSON.parse(raw);if(draft.version!==project.version){status('An older recovery buffer exists. Export current work before recovering it.',true);return;}source=draft.source;sectionPath=draft.path;sectionMode=!!draft.path;await showEditor(sectionMode);$('editor').value=draft.buffer;markDirty();size();}catch{status('Browser recovery buffer could not be loaded.',true);}}

function askDialog(message, initial, confirmation){return new Promise(resolve=>{const dialog=node('dialog');const title=node('h2',confirmation?'Confirm action':'Name your checkpoint');const detail=node('p',message);const input=node('input');input.value=initial||'';input.setAttribute('aria-label',message);const controls=node('div',undefined,'dialog-actions');const cancel=node('button','Cancel'),ok=node('button',confirmation?'Continue':'Create checkpoint','primary');controls.append(cancel,ok);dialog.append(title,detail);if(!confirmation)dialog.append(input);dialog.append(controls);document.body.append(dialog);const finish=value=>{dialog.close();dialog.remove();resolve(value);};cancel.onclick=()=>finish(confirmation?false:null);ok.onclick=()=>finish(confirmation?true:input.value.trim());dialog.addEventListener('cancel',e=>{e.preventDefault();finish(confirmation?false:null);});dialog.showModal();(confirmation?ok:input).focus();});}
const askConfirm=message=>askDialog(message,'',true);
const askText=(message,initial)=>askDialog(message,initial,false);

function setupCommunityValidation(){
 const button=node('button','Send to community validator');button.title='Send the current GameState to api.unofficial.voyage for supplementary schema and authoring checks';$('runValidation').after(button);
 const explanation=node('p','Local checks cover JSON structure and selected references. Voyage checks official draft acceptance. Send to community validator submits your GameState to api.unofficial.voyage, an independent service, without your Creator API key. Its schema and authoring checks supplement official validation.','small');$('panel-validation').querySelector('.view-heading').after(explanation);
 button.onclick=run(async()=>{
  if(!project)return;
  const pid=project.id,epoch=validationEpoch;
  if(project?.id!==pid||validationEpoch!==epoch){status('Document changed. Start community validation again.');return;}
  button.disabled=true;
  try{
   const candidate=await fullText();await showTab('validation');
   const result=await api('/api/community/validate',{text:candidate,consent:true});
   if(project?.id!==pid||validationEpoch!==epoch){status('Document changed during community validation. Run it again for current results.');return;}
   const host=$('validation');host.replaceChildren(node('strong','Unofficial Voyage community validation','validation-source'));
   host.append(node('p',`Source: ${result.source} · Validator version: ${result.validatorVersion||'not reported'} · Checked ${new Date().toLocaleTimeString()}`,'small'));
   host.append(node('div',result.errors.length?`${result.errors.length} community error(s) reported.`:'No community errors reported. Official Voyage acceptance and gameplay behavior remain separate checks.',result.errors.length?'check error':'check'));
   for(const [kind,label,cls]of [['errors','Error','error'],['warnings','Warning','warning'],['recommendations','Recommendation','recommendation']])for(const issue of result[kind]){
    const row=node('article',undefined,`check ${cls}`);
    if(typeof issue==='string')row.append(node('div',`${label}: ${issue}`));
    else{row.append(node('strong',`${label}: ${issue.title||issue.message||'Validation issue'}`));if(issue.path)row.append(node('div',typeof issue.path==='string'?issue.path:JSON.stringify(issue.path)));if(issue.message&&issue.title)row.append(node('p',issue.message));if(issue.detail)row.append(node('p',typeof issue.detail==='string'?issue.detail:JSON.stringify(issue.detail)));if(issue.fix)row.append(node('p',`Suggested fix: ${typeof issue.fix==='string'?issue.fix:JSON.stringify(issue.fix)}`));}
    host.append(row);
   }
   const fingerprint=node('p',`Document SHA-256: ${result.documentHash}`,'small');fingerprint.style.overflowWrap='anywhere';host.append(fingerprint);status(`Community validation finished: ${result.errors.length} errors, ${result.warnings.length} warnings, ${result.recommendations.length} recommendations.`);
  }catch(error){if(project?.id===pid&&validationEpoch===epoch)$('validation').replaceChildren(node('div',`Community validation unavailable: ${error.message}`,'check error'));throw error;}finally{button.disabled=false;}
 });
}
setupCommunityValidation();
